// ── Long-context haystack ─────────────────────────────────────────────────────────────

var (
	hsCities = []string{"Lisbon", "Porto", "Montreal", "Lyon", "Valencia", "Recife", "Toronto", "Quebec",
		"Bilbao", "Curitiba", "Marseille", "Seville", "Halifax", "Nantes", "Braga", "Rosario"}
	hsGoods = []string{"copper wire", "oat flour", "solar panels", "bicycle frames", "olive oil",
		"ceramic tiles", "wool blankets", "lithium cells", "coffee beans", "steel bolts", "paper rolls"}
	hsVerbs = []string{"received", "dispatched", "inspected", "rejected", "re-labelled", "counted"}
)

// haystack returns filler logistics records of roughly nChars characters, with needle
// inserted at the given depth (0..1). Records are pseudo-random but deterministic (LCG),
// so every model sees byte-identical prompts.
func haystack(nChars int, needle string, depth float64) string {
	var b strings.Builder
	seed := uint32(20260924)
	next := func(n int) int { seed = seed*1664525 + 1013904223; return int(seed>>8) % n }
	inserted := false
	for i := 0; b.Len() < nChars; i++ {
		if !inserted && float64(b.Len()) >= depth*float64(nChars) {
			b.WriteString(needle + "\n")
			inserted = true
		}
		fmt.Fprintf(&b, "Record %05d: the %s depot %s %d crates of %s on day %d; supervisor badge %04d.\n",
			i, hsCities[next(len(hsCities))], hsVerbs[next(len(hsVerbs))], 3+next(400),
			hsGoods[next(len(hsGoods))], 1+next(365), next(10000))
	}
	if !inserted {
		b.WriteString(needle + "\n")
	}
	return b.String()
}

